// utils/bridge/{bridge}/{Bridge}Abstraction.ts
import type { {Bridge}Renderer, {Bridge}Format } from './interfaces'
import { {bridge}Renderers } from './{Bridge}Renderers'

// Abstraction de base — logique commune
export abstract class {Bridge}Abstraction {
  constructor(protected renderer: {Bridge}Renderer) {}

  // Point d'entrée commun
  execute(data: Record<string, unknown>[], context: string): void {
    const prepared = this.prepare(data)
    this.renderer.render(prepared, context)
  }

  // Chaque abstraction concrète prépare les données différemment
  protected abstract prepare(data: Record<string, unknown>[]): Record<string, unknown>[]
}

// Abstraction concrète — logique métier spécifique
export class {Bridge}ConcreteAbstraction extends {Bridge}Abstraction {
  protected prepare(data: Record<string, unknown>[]): Record<string, unknown>[] {
    // Ajoute ici la transformation des données avant rendu
    // Exemple : sélectionner/renommer les colonnes pour l'export
    return data.map(item => ({
      // Ajoute ici le mapping des champs
    }))
  }
}

// Factory — assemble abstraction + implémentation
export const create{Bridge} = (
  type: 'concrete',
  format: {Bridge}Format
): {Bridge}Abstraction => {
  const renderer = {bridge}Renderers[format]
  const abstractions = {
    concrete: {Bridge}ConcreteAbstraction
  }
  return new abstractions[type](renderer)
}

// composables/use{Bridge}.ts
import { create{Bridge} } from '~/utils/bridge/{bridge}/{Bridge}Abstraction'
import type { {Bridge}Format } from '~/utils/bridge/{bridge}/interfaces'

export const use{Bridge} = () => {
  const execute = (
    data: Record<string, unknown>[],
    format: {Bridge}Format,
    context: string
  ) => {
    // Bridge : l'abstraction et le renderer évoluent séparément
    const bridge = create{Bridge}('concrete', format)
    bridge.execute(data, context)
  }

  return { execute }
}

// tests/utils/bridge/{bridge}/{Bridge}Abstraction.spec.ts
import { describe, it, expect, vi } from 'vitest'
import { create{Bridge}, {Bridge}ConcreteAbstraction } from '~/utils/bridge/{bridge}/{Bridge}Abstraction'
import type { {Bridge}Renderer } from '~/utils/bridge/{bridge}/interfaces'

const mockRenderer: {Bridge}Renderer = {
  render: vi.fn()
}

const mockData = [
  { id: 1 },
  { id: 2 }
]

describe('{Bridge}Abstraction', () => {

  beforeEach(() => vi.clearAllMocks())

  it('execute() prépare les données et appelle le renderer', () => {
    const bridge = new {Bridge}ConcreteAbstraction(mockRenderer)
    bridge.execute(mockData, 'test')
    expect(mockRenderer.render).toHaveBeenCalledOnce()
  })

  it('le renderer reçoit les données préparées', () => {
    const bridge = new {Bridge}ConcreteAbstraction(mockRenderer)
    bridge.execute(mockData, 'test')
    const [calledData] = (mockRenderer.render as any).mock.calls[0]
    expect(Array.isArray(calledData)).toBe(true)
  })

  it('create{Bridge}() assemble la bonne abstraction avec le bon renderer', () => {
    const bridge = create{Bridge}('concrete', 'formatA')
    expect(bridge).toBeInstanceOf({Bridge}ConcreteAbstraction)
  })

  it('changer de format ne modifie pas la logique de préparation', () => {
    const bridgeA = create{Bridge}('concrete', 'formatA')
    const bridgeB = create{Bridge}('concrete', 'formatB')
    // Les deux utilisent la même logique de préparation
    expect(bridgeA).toBeInstanceOf({Bridge}ConcreteAbstraction)
    expect(bridgeB).toBeInstanceOf({Bridge}ConcreteAbstraction)
  })

})

